derStatus {\n    Ok,\n    Complete,\n    Invalid,\n    Limit,\n    Malformed,\n}\n\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\npub enum TagKind {\n    StartElement,\n    EndElement,\n    EmptyElement,\n}\n\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\npub struct ReaderTag {\n    pub kind: TagKind,\n    pub source: Span,\n    pub name: Span,\n    pub attribute_count: usize,\n}\n\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\npub struct ReaderProgress {\n    pub bytes_read: usize,\n    pub source_bytes: usize,\n    pub diagnostic: Diagnostic,\n    pub complete: bool,\n}\n\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\nenum Mode { Text, Probe, Tag, Comment, Cdata, Pi, Doctype }\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\nenum Probe { None, Comment, Cdata, Doctype }\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\nenum DoctypePhase { Start, Main, Quote, Subset, SubsetQuote, Lt, Bang, BangDash, Comment, Pi }\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\nenum DoctypeResult { More, Done, Bad }\n\n#[derive(Debug, Clone, Copy)]\nstruct DoctypeState {\n    phase: DoctypePhase,\n    quote: u8,\n    run: u8,\n    subset_closed: bool,\n}\n\nimpl Default for DoctypeState {\n    fn default() -> Self {\n        Self { phase: DoctypePhase::Start, quote: 0, run: 0, subset_closed: false }\n    }\n}\n\nimpl DoctypeState {\n    fn step(&mut self, byte: u8) -> DoctypeResult {\n        loop {\n            match self.phase {\n                DoctypePhase::Start => {\n                    if !is_xml_whitespace(byte) { return DoctypeResult::Bad; }\n                    self.phase = DoctypePhase::Main;\n                    return DoctypeResult::More;\n                }\n                DoctypePhase::Main => match byte {\n                    b'\"' | b'\\'' => { self.quote = byte; self.phase = DoctypePhase::Quote; }\n                    b'[' => {\n                        if self.subset_closed { return DoctypeResult::Bad; }\n                        self.phase = DoctypePhase::Subset;\n                    }\n                    b'>' => return DoctypeResult::Done,\n                    b'<' => return DoctypeResult::Bad,\n                    _ => {}\n                },\n                DoctypePhase::Quote => if byte == self.quote { self.phase = DoctypePhase::Main; },\n                DoctypePhase::Subset => match byte {\n                    b'\"' | b'\\'' => { self.quote = byte; self.phase = DoctypePhase::SubsetQuote; }\n                    b'<' => self.phase = DoctypePhase::Lt,\n                    b']' => { self.subset_closed = true; self.phase = DoctypePhase::Main; }\n                    _ => {}\n                },\n                DoctypePhase::SubsetQuote => if byte == self.quote { self.phase = DoctypePhase::Subset; },\n                DoctypePhase::Lt => match byte {\n                    b'!' => { self.phase = DoctypePhase::Bang; return DoctypeResult::More; }\n                    b'?' => { self.run = 0; self.phase = DoctypePhase::Pi; return DoctypeResult::More; }\n                    _ => { self.phase = DoctypePhase::Subset; continue; }\n                },\n                DoctypePhase::Bang => if byte == b'-' { self.phase = DoctypePhase::BangDash; return DoctypeResult::More; } else { self.phase = DoctypePhase::Subset; continue; },\n                DoctypePhase::BangDash => if byte == b'-' { self.run = 0; self.phase = DoctypePhase::Comment; return DoctypeResult::More; } else { self.phase = DoctypePhase::Subset; continue; },\n                DoctypePhase::Comment => {\n                    if byte == b'-' { self.run = self.run.saturating_add(1).min(2); }\n                    else if byte == b'>' && self.run >= 2 { self.phase = DoctypePhase::Subset; }\n                    else { self.run = 0; }\n                }\n                DoctypePhase::Pi => {\n                    if byte == b'>' && self.run == 1 { self.phase = DoctypePhase::Subset; }\n                    else { self.run = u8::from(byte == b'?'); }\n                }\n            }\n            return DoctypeResult::More;\n        }\n    }\n}\n\n/// Borrowing scanner. Source bytes remain immutable and are never normalized.\npub struct XmlReader<'a> {\n    source: &'a [u8],\n    bytes_read: usize,\n    token_start: usize,\n    name_offset: usize,\n    name_length: usize,\n    attribute_count: usize,\n    probe_position: usize,\n    mode: Mode,\n    probe: Probe,\n    closing: bool,\n    name_complete: bool,\n    in_quote: bool,\n    pending_slash: bool,\n    self_closing: bool,\n    quote: u8,\n    complete: bool,\n    element_seen: bool,\n    doctype_seen: bool,\n    doctype: DoctypeState,\n    diagnostic: Diagnostic,\n}\n\nimpl<'a> XmlReader<'a> {\n    /// Starts a reader borrowing `source` until this reader is dropped.\n    pub fn new(source: &'a [u8]) -> Result<Self, ReaderStatus> {\n        if source.len() > MAX_READER_SOURCE_BYTES { return Err(ReaderStatus::Limit); }\n        Ok(Self {\n            source, bytes_read: 0, token_start: 0, name_offset: 0, name_length: 0,\n            attribute_count: 0, probe_position: 0, mode: Mode::Text, probe: Probe::None,\n            closing: false, name_complete: false, in_quote: false, pending_slash: false,\n            self_closing: false, quote: 0, complete: false, element_seen: false,\n            doctype_seen: false, doctype: DoctypeState::default(), diagnostic: Diagnostic::clear(),\n        })\n    }\n\n    /// Advances by at most `byte_budget` bytes, capped at 64 KiB, and emits\n    /// complete lexical tags. Returning false from the callback is an error.\n    pub fn step<F>(&mut self, byte_budget: usize, mut on_tag: F) -> ReaderStatus\n    where F: FnMut(ReaderTag) -> bool {\n        if byte_budget == 0 { return ReaderStatus::Invalid; }\n        if self.diagnostic.category != XmlError::None { return ReaderStatus::Malformed; }\n        if self.complete { return ReaderStatus::Complete; }\n        let budget = byte_budget.min(MAX_READER_STEP_BYTES);\n        let end = self.bytes_read.saturating_add(budget).min(self.source.len());\n        while self.bytes_read < end && self.diagnostic.category == XmlError::None {\n            let at = self.bytes_read;\n            let byte = self.source[at];\n            match self.mode {\n                Mode::Text => if byte == b'<' {\n                    self.mode = Mode::Probe;\n                    self.token_start = at;\n                    self.probe = Probe::None;\n                    self.probe_position = 0;\n                },\n                Mode::Probe => self.scan_probe(byte, at),\n                Mode::Tag => {\n                    if !self.name_complete {\n                        if is_reader_name_byte(byte) {\n                            if self.name_length == MAX_READER_NAME_BYTES { self.fail(XmlError::InvalidName, self.name_offset); }\n                            else { self.name_length += 1; }\n                            self.bytes_read += 1;\n                            continue;\n                        }\n                        if self.name_length == 0 { self.fail(XmlError::InvalidName, self.name_offset); }\n                        else { self.name_complete = true; }\n                    }\n                    if self.in_quote {\n                        if byte == self.quote { self.in_quote = false; }\n                    } else if byte == b'\\'' || byte == b'\"' {\n                        self.in_quote = true;\n                        self.quote = byte;\n                        self.attribute_count = self.attribute_count.saturating_add(1);\n                    } else if byte == b'/' { self.pending_slash = true; }\n                    else if byte == b'>' {\n                        self.self_closing = self.pending_slash;\n                        if !self.emit_tag(at + 1, &mut on_tag) { break; }\n                    } else { self.pending_slash = false; }\n                }\n                Mode::Comment if byte == b'>' && at >= 2 && &self.source[at - 2..at] == b\"--\" => self.mode = Mode::Text,\n                Mode::Cdata if byte == b'>' && at >= 2 && &self.source[at - 2..at] == b\"]]\" => self.mode = Mode::Text,\n                Mode::Doctype => match self.doctype.step(byte) {\n                    DoctypeResult::Bad => self.fail(XmlError::MalformedSyntax, at),\n                    DoctypeResult::Done => self.mode = Mode::Text,\n                    DoctypeResult::More => {}\n                },\n                Mode::Pi if byte == b'>' && at > 0 && self.source[at - 1] == b'?' => self.mode = Mode::Text,\n                _ => {}\n            }\n            self.bytes_read += 1;\n        }\n        if self.diagnostic.category != XmlError::None { return ReaderStatus::Malformed; }\n        if self.bytes_read == self.source.len() {\n            if self.mode != Mode::Text { self.fail(XmlError::IncompleteDocument, self.source.len()); }\n            else { self.complete = true; }\n        }\n        if self.diagnostic.category == XmlError::None {\n            if self.complete { ReaderStatus::Complete } else { ReaderStatus::Ok }\n        } else { ReaderStatus::Malformed }\n    }\n\n    pub fn progress(&self) -> ReaderProgress {\n        ReaderProgress { bytes_read: self.bytes_read, source_bytes: self.source.len(), diagnostic: self.diagnostic, complete: self.complete }\n    }\n\n    fn scan_probe(&mut self, byte: u8, at: usize) {\n        if self.probe_position == 0 {\n            if byte == b'?' { self.mode = Mode::Pi; }\n            else if byte == b'/' {\n                self.begin_tag(true, at + 1);\n            } else if byte == b'!' { self.probe_position = 1; }\n            else if is_reader_name_byte(byte) {\n                self.begin_tag(false, at);\n                self.name_length = 1;\n            } else { self.fail(XmlError::InvalidName, at); }\n        } else if self.probe == Probe::None {\n            if byte == b'-' { self.probe = Probe::Comment; self.probe_position = 1; }\n            else if byte == b'[' { self.probe = Probe::Cdata; self.probe_position = 1; }\n            else if byte == b'D' && !self.doctype_seen && !self.element_seen {\n                self.probe = Probe::Doctype;\n                self.probe_position = 1;\n            } else { self.fail(XmlError::UnsupportedDtd, self.token_start); }\n        } else if self.probe == Probe::Comment {\n            if byte != b'-' { self.fail(XmlError::MalformedSyntax, self.token_start); }\n            else { self.mode = Mode::Comment; }\n        } else if self.probe == Probe::Doctype {\n            const TAIL: &[u8] = b\"OCTYPE\";\n            let index = self.probe_position - 1;\n            if TAIL.get(index).copied() != Some(byte) { self.fail(XmlError::UnsupportedDtd, self.token_start); }\n            else if self.probe_position == TAIL.len() {\n                self.mode = Mode::Doctype;\n                self.doctype_seen = true;\n                self.doctype = DoctypeState::default();\n            } else { self.probe_position += 1; }\n        } else {\n            const TAIL: &[u8] = b\"CDATA[\";\n            let index = self.probe_position - 1;\n            if index >= TAIL.len() || TAIL[index] != byte { self.fail(XmlError::MalformedSyntax, self.token_start); }\n            else if self.probe_position == TAIL.len() { self.mode = Mode::Cdata; }\n            else { self.probe_position += 1; }\n        }\n    }\n\n    fn begin_tag(&mut self, closing: bool, name_offset: usize) {\n        self.mode = Mode::Tag;\n        self.closing = closing;\n        self.name_offset = name_offset;\n        self.name_length = 0;\n        self.attribute_count = 0;\n        self.name_complete = false;\n        self.pending_slash = false;\n    }\n\n    fn emit_tag<F>(&mut self, end: usize, callback: &mut F) -> bool\n    where F: FnMut(ReaderTag) -> bool {\n        if self.name_length == 0 || self.name_length > MAX_READER_NAME_BYTES {\n            self.fail(XmlError::InvalidName, self.name_offset);\n            return false;\n        }\n        if !self.closing { self.element_seen = true; }\n        let kind = if self.closing { TagKind::EndElement } else if self.self_closing { TagKind::EmptyElement } else { TagKind::StartElement };\n        let tag = ReaderTag {\n            kind,\n            source: Span { start: self.token_start, end },\n            name: Span { start: self.name_offset, end: self.name_offset + self.name_length },\n            attribute_count: self.attribute_count,\n        };\n        if !callback(tag) {\n            self.fail(XmlError::OutputExhausted, self.token_start);\n            return false;\n        }\n        self.mode = Mode::Text;\n        true\n    }\n\n    fn fail(&mut self, category: XmlError, offset: usize) {\n        if self.diagnostic.category == XmlError::None {\n            self.diagnostic = Diagnostic { category, offset: offset.min(self.source.len()) };\n        }\n    }\n}\n\nfn is_reader_name_byte(byte: u8) -> bool {\n    byte.is_ascii_alphanumeric() || byte >= 0x80 || matches!(byte, b'_' | b'-' | b'.' | b':')\n}\n\n#[cfg(test)]\nmod tests;\nuse crate::{is_name_char, is_name_start, is_xml_char, is_xml_whitespace};\nuse crate::tokenizer::{validate_declaration, MAX_ATTRIBUTES_PER_ELEMENT, MAX_DEPTH, MAX_LARGE_INPUT_BYTES,\n    MAX_NODES, MAX_TOKEN_NAME_BYTES};\nuse crate::{StreamStatus, TokenKind, XmlDiagnostic, XmlError, XmlLimits, XmlResult, XmlSpan, XmlToken};\nuse core::mem::size_of;\nuse crate::utf8_scan::Utf8Scan;\n\nconst STEP_CAP: usize = 64 * 1024;\n\n#[derive(Clone, Copy)]\nstruct NameScan {\n    start: usize, pos: usize, first_colon: Option<usize>, utf8: Utf8Scan,\n    leading_colon: bool, trailing_colon: bool, local_first_valid: Option<bool>, classification: NameClass,\n}\nimpl NameScan {\n    fn new(start: usize) -> Self {\n        Self { start, pos: start, first_colon: None, utf8: Utf8Scan::default(),\n            leading_colon: false, trailing_colon: false, local_first_valid: None, classification: NameClass::new() }\n    }\n}\n\n/// Every variable token-name source load, including comparison operands, uses\n/// this budget gate. The legacy `reads` counter measures scanner loads only;\n/// `total_reads` includes scanner and comparison loads without cursor inference.\n#[derive(Default)]\nstruct NameWork {\n    remaining: usize, spent: usize,\n    #[cfg(test)] reads: usize,\n    #[cfg(test)] decoder_inputs: usize,\n    #[cfg(test)] comparison_reads: usize,\n    #[cfg(test)] total_reads: usize,\n}\nimpl NameWork {\n    fn begin(&mut self, budget: usize) { self.remaining=budget;self.spent=0; }\n    fn load(&mut self, source: &[u8], at: usize, comparison: bool) -> Option<u8> {\n        if self.remaining==0{return None}\n        self.remaining-=1;self.spent+=1;\n        let byte=source[at];\n        #[cfg(test)] {\n            self.total_reads+=1;\n            if comparison{self.comparison_reads+=1}else{self.reads+=1}\n        }\n        #[cfg(not(test))] let _=comparison;\n        Some(byte)\n    }\n    fn read(&mut self, source: &[u8], at: usize) -> Option<u8> { self.load(source,at,false) }\n    fn decode(&mut self, utf8: &mut Utf8Scan, byte: u8, at: usize) -> Result<Option<u32>, usize> {\n        #[cfg(test)] { self.decoder_inputs += 1; }\n        utf8.push(byte, at)\n    }\n}\n\nconst ENTITIES: [&[u8]; 5]=[b\"lt\",b\"gt\",b\"amp\",b\"apos\",b\"quot\"];\n#[derive(Clone, Copy)]\nstruct NameClass { xml_exact: bool, xml_folded: bool, entities: u8 }\nimpl NameClass {\n    fn new()->Self{Self{xml_exact:true,xml_folded:true,entities:31}}\n    fn push(&mut self,cp:u32,offset:usize){\n        self.xml_exact&=b\"xml\".get(offset).is_some_and(|v|u32::from(*v)==cp);\n        self.xml_folded&=cp<128&&b\"xml\".get(offset).is_some_and(|v|*v==(cp as u8).to_ascii_lowercase());\n        for (i,name) in ENTITIES.iter().enumerate(){\n            if !name.get(offset).is_some_and(|v|u32::from(*v)==cp){self.entities&=!(1<<i)}\n        }\n    }\n    fn known_entity(self,len:usize)->bool{ENTITIES.iter().enumerate().any(|(i,n)|self.entities&(1<<i)!=0&&n.len()==len)}\n}\n\n#[derive(Clone, Copy)]\nstruct NameCompare { left:XmlSpan, right:XmlSpan, index:usize, left_byte:Option<u8> }\n#[derive(PartialEq, Eq)]\nenum CompareStatus { Pending, Equal, Different, Canceled }\nimpl NameCompare {\n    fn new(left:XmlSpan,right:XmlSpan)->Self{Self{left,right,index:0,left_byte:None}}\n    fn step<C:FnMut()->bool>(&mut self,source:&[u8],work:&mut NameWork,cancel:&mut C)->CompareStatus{\n        if self.left.length!=self.right.length{return CompareStatus::Different}\n        while self.index<self.left.length{\n            if work.remaining==0{return CompareStatus::Pending}\n            if cancel(){return CompareStatus::Canceled}\n            if self.left_byte.is_none(){\n                self.left_byte=work.load(source,self.left.offset+self.index,true);\n                continue\n            }\n            let Some(right)=work.load(source,self.right.offset+self.index,true)else{return CompareStatus::Pending};\n            if self.left_byte.take()!=Some(right){return CompareStatus::Different}\n            self.index+=1;\n        }\n        CompareStatus::Equal\n    }\n}\n#[derive(Clone, Copy)]\nenum RefMode { Start, Numeric { hex: bool, digits: usize, value: u32 }, Named(NameScan) }\n#[derive(Clone, Copy)]\nstruct RefScan { start: usize, pos: usize, mode: RefMode }\n#[derive(Clone, Copy, Default)]\nstruct NameParts { name: XmlSpan, prefix: XmlSpan, local: XmlSpan, xml_exact:bool, xml_folded:bool, entity_known:bool }\n\n#[derive(Clone, Copy, PartialEq, Eq)]\nenum DtdPhase { Start, Main, Quote, Subset, SubsetQuote, Lt, Bang, BangDash, Comment, Pi }\n#[derive(Clone, Copy)]\nstruct Dtd { phase: DtdPhase, quote: u8, run: u8, subset_closed: bool }\nimpl Default for Dtd { fn default() -> Self { Self { phase: DtdPhase::Start, quote: 0, run: 0, subset_closed: false } } }\nimpl Dtd {\n    fn step(&mut self, c: u8) -> Result<bool, ()> {\n        loop { match self.phase {\n            DtdPhase::Start => { if !is_xml_whitespace(c) { return Err(()) } self.phase=DtdPhase::Main; return Ok(false) },\n            DtdPhase::Main => match c { b'\"'|b'\\''=>{self.quote=c;self.phase=DtdPhase::Quote},b'['=>{if self.subset_closed{return Err(())}self.phase=DtdPhase::Subset},b'>'=>return Ok(true),b'<'=>return Err(()),_=>{} },\n            DtdPhase::Quote=>if c==self.quote{self.phase=DtdPhase::Main},\n            DtdPhase::Subset=>match c {b'\"'|b'\\''=>{self.quote=c;self.phase=DtdPhase::SubsetQuote},b'<'=>self.phase=DtdPhase::Lt,b']'=>{self.subset_closed=true;self.phase=DtdPhase::Main},_=>{}},\n            DtdPhase::SubsetQuote=>if c==self.quote{self.phase=DtdPhase::Subset},\n            DtdPhase::Lt=>match c{b'!'=>{self.phase=DtdPhase::Bang;return Ok(false)},b'?'=>{self.run=0;self.phase=DtdPhase::Pi;return Ok(false)},_=>{self.phase=DtdPhase::Subset;continue}},\n            DtdPhase::Bang=>if c==b'-'{self.phase=DtdPhase::BangDash;return Ok(false)}else{self.phase=DtdPhase::Subset;continue},\n            DtdPhase::BangDash=>if c==b'-'{self.run=0;self.phase=DtdPhase::Comment;return Ok(false)}else{self.phase=DtdPhase::Subset;continue},\n            DtdPhase::Comment=>if c==b'-'{self.run=(self.run+1).min(2)}else if c==b'>'&&self.run>=2{self.phase=DtdPhase::Subset}else{self.run=0},\n            DtdPhase::Pi=>if c==b'>'&&self.run==1{self.phase=DtdPhase::Subset}else{self.run=u8::from(c==b'?')},\n        } return Ok(false) }\n    }\n}\n\n#[derive(Clone, Copy, PartialEq, Eq)]\nenum TagPhase { Prefix, Name, EndMatch, Between, EmptyClose, AttrName, AttrMatch, AttrEq, AttrQuote, AttrValue, EndBetween }\nstruct TagState { start:usize, pos:usize, closing:bool, phase:TagPhase, name_scan:Option<NameScan>, name:Option<NameParts>,\n    attr_scan:Option<NameScan>, attr:Option<NameParts>, attr_start:usize, value_start:usize, quote:u8,\n    local_attrs:usize, separated:bool, token_index:usize, reference:Option<RefScan>, comparison:Option<NameCompare>, duplicate_index:usize }\nimpl TagState { fn new(start:usize,closing:bool)->Self {Self{start,pos:start,closing,phase:TagPhase::Prefix,name_scan:None,name:None,attr_scan:None,attr:None,attr_start:0,value_start:0,quote:0,local_attrs:0,separated:false,token_index:0,reference:None,comparison:None,duplicate_index:0}} }\n\nenum Pending {\n    None,\n    Text { start:usize, pos:usize, nonspace:bool, first_nonspace:usize, reference:Option<RefScan> },\n    Comment { start:usize, pos:usize, dashes:u8 },\n    Cdata { start:usize, pos:usize, brackets:u8 },\n    Doctype { start:usize, pos:usize, state:Dtd },\n    Pi { start:usize, pos:usize, name_scan:Option<NameScan>, name:Option<XmlSpan>, declaration:bool, data:Option<usize>, separating:bool, question:bool },\n}\n\npub struct XmlTokenStream<'a> {\n    source:&'a [u8], limits:XmlLimits, result:XmlResult, tokens:Vec<XmlToken>,\n    tag_scratch:Vec<XmlToken>, token_capacity:usize, visitor_mode:bool,\n    cursor:usize, parse_limit:usize, char_cursor:usize, utf8:Utf8Scan, name_work:NameWork,\n    chars_complete:bool, depth:usize, roots:usize, total_attrs:usize, open_names:Vec<XmlSpan>,\n    pending:Pending, tag:Option<TagState>, doctype_seen:bool, complete:bool, canceled:bool, failed:bool, taken:bool,\n}\n\nimpl<'a> XmlTokenStream<'a> {\n    pub fn new(source:&'a [u8],max_storage_bytes:usize)->Result<Self,StreamStatus>{\n        if max_storage_bytes<size_of::<XmlToken>(){return Err(StreamStatus::Failed)}\n        Self::construct(source,max_storage_bytes,false)\n    }\n    pub fn new_visitor(source:&'a [u8])->Result<Self,StreamStatus>{\n        let scratch=MAX_ATTRIBUTES_PER_ELEMENT.checked_add(1).and_then(|n|n.checked_mul(size_of::<XmlToken>())).ok_or(StreamStatus::Failed)?;\n        Self::construct(source,scratch,true)\n    }\n    fn construct(source:&'a [u8],max_storage_bytes:usize,visitor_mode:bool)->Result<Self,StreamStatus>{\n        if source.len()>MAX_LARGE_INPUT_BYTES{return Err(StreamStatus::Failed)}\n        let limits=XmlLimits{input_bytes:MAX_LARGE_INPUT_BYTES,..XmlLimits::default()};\n        let mut tag_scratch=Vec::new();\n        if visitor_mode&&tag_scratch.try_reserve_exact(MAX_ATTRIBUTES_PER_ELEMENT+1).is_err(){return Err(StreamStatus::Failed)}\n        let mut open_names=Vec::new();if open_names.try_reserve_exact(MAX_DEPTH).is_err(){return Err(StreamStatus::Failed)}\n        let cursor=if source.starts_with(b\"\\xef\\xbb\\xbf\"){3}else{0};\n        Ok(Self{source,limits,result:XmlResult::default(),tokens:Vec::new(),tag_scratch,token_capacity:max_storage_bytes/size_of::<XmlToken>(),visitor_mode,\n            cursor,parse_limit:cursor,char_cursor:0,utf8:Utf8Scan::default(),name_work:NameWork::default(),chars_complete:false,depth:0,roots:0,total_attrs:0,open_names,\n            pending:Pending::None,tag:None,doctype_seen:false,complete:false,canceled:false,failed:false,taken:false})\n    }\n\n    pub(crate) fn with_limits(source:&'a [u8],limits:XmlLimits,token_capacity:usize)->Result<Self,StreamStatus>{\n        let mut stream=Self::construct(source,0,false)?;\n        stream.limits=limits;stream.token_capacity=token_capacity;Ok(stream)\n    }\n\n    pub fn step(&mut self,budget:usize,canceled:bool)->StreamStatus{\n        let mut poll=||canceled;\n        self.step_inner(budget,&mut poll,None)\n    }\n    pub fn step_with_visitor<F:FnMut(&XmlToken)->bool>(&mut self,budget:usize,canceled:bool,visitor:&mut F)->StreamStatus{\n        let mut poll=||canceled;\n        self.step_inner(budget,&mut poll,Some(visitor))\n    }\n    pub fn step_with_visitor_and_cancel<F:FnMut(&XmlToken)->bool,C:FnMut()->bool>(&mut self,budget:usize,visitor:&mut F,cancel:&mut C)->StreamStatus{\n        self.step_inner(budget,cancel,Some(visitor))\n    }\n    pub fn step_with_cancel<C:FnMut()->bool>(&mut self,budget:usize,cancel:&mut C)->StreamStatus{\n        self.step_inner(budget,cancel,None)\n    }\n    fn step_inner<C:FnMut()->bool>(&mut self,budget:usize,cancel:&mut C,mut visitor:Option<&mut dyn FnMut(&XmlToken)->bool>)->StreamStatus{\n        let status=self.advance_step(budget,cancel,&mut visitor);\n        if matches!(status,St